import{X as e,Y as t,lt as n,n as r}from"./chunks/framework.CDweLSlD.js";var i=JSON.parse(`{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/concepts.md","filePath":"fr/guide/concepts.md"}`),a={name:`fr/guide/concepts.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to “Concepts”">​</a></h1><p>Les idées de D3Pict, et les mots que la documentation emploie.</p><h2 id="de-la-donnee-au-pixel" tabindex="-1">De la donnée au pixel <a class="header-anchor" href="#de-la-donnee-au-pixel" aria-label="Permalink to “De la donnée au pixel”">​</a></h2><p>Tout ce que fait la bibliothèque est une chaîne qui va de vos valeurs à une position à l&#39;écran :</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vos valeurs ──▶ domain ──axe──▶ range ──système──▶ pixels</span></span>
<span class="line"><span> (une date, 42.5,  (la partie des     (les unités du    (le tracé</span></span>
<span class="line"><span>  une catégorie)    données qu&#39;un      système de        du graphique)</span></span>
<span class="line"><span>                    axe montre)        coordonnées)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Espace</th><th>Ce que c&#39;est</th><th>Exemple</th></tr></thead><tbody><tr><td>domain</td><td>les valeurs de vos données le long d&#39;un axe</td><td>une date, <code>42.5</code>, une catégorie</td></tr><tr><td>range</td><td>les unités d&#39;un système de coordonnées</td><td>pixels (cartésien), radians et distance (polaire)</td></tr><tr><td>pixel</td><td>le tracé du graphique</td><td>un point du SVG</td></tr></tbody></table><p>Un <strong>axe</strong> projette un domain sur un range avec une <em>échelle</em>. Un <strong>système de coordonnées</strong> projette un range sur des pixels. Un <strong>rendu</strong> lit une série, demande des positions aux axes et au système, et dessine. Comme le rendu ne parle qu&#39;aux axes et au système, le même rendu dessine dans un rectangle ou sur un disque : changez les axes, pas le rendu.</p><h2 id="le-graphique-et-ses-objets" tabindex="-1">Le graphique et ses objets <a class="header-anchor" href="#le-graphique-et-ses-objets" aria-label="Permalink to “Le graphique et ses objets”">​</a></h2><p>Un <code>D3PChart</code> est un SVG vide dans un conteneur. Tout le reste est un <strong>objet</strong> attaché avec <code>addToChart(chart)</code> (ou listé dans les <code>objects</code> d&#39;un graphique Vue ou React) : axes, rendus, curseur, infobulle, outils, titres. Un objet sert autant de graphiques qu&#39;on lui en attache : le même outil peut piloter deux graphiques, et une infobulle peut en couvrir plusieurs.</p><p>Les objets se créent avec des options, et la plupart ont des <code>props</code> : des réglages qu&#39;on peut lire et changer à tout moment (<code>line.props({ style: { color: &#39;tomato&#39; } })</code>). Le graphique se redessine tout seul.</p><p>On retire un objet avec <code>removeFromChart(chart)</code> et on le libère avec <code>destroy()</code>. Détruire un graphique détache tout ce qui lui est attaché.</p><p>Chaque objet prend un <code>bus</code> : le canal par lequel les objets se parlent. Utilisez le même partout (<a href="/fr/guide/advanced">Avancé</a> dit ce qui y passe). Un graphique et les objets qui lui sont attachés doivent partager un bus.</p><h2 id="series" tabindex="-1">Séries <a class="header-anchor" href="#series" aria-label="Permalink to “Séries”">​</a></h2><p>Une <code>D3PSeries</code> est vos données : un nom, et des lignes de valeurs. La première colonne est <code>x</code>, la deuxième la valeur principale ; une série peut avoir d&#39;autres colonnes, nommées (un <code>min</code> et un <code>max</code>, un <code>open</code>, <code>high</code>, <code>low</code> et <code>close</code>). Elle accepte des nombres, des lignes positionnelles, des objets, des colonnes, tout itérable. Quand ses données changent, ce qui la dessine suit. Voir l&#39;<a href="/fr/guide/series-and-style">étape 3</a>.</p><p>Des séries peuvent être dérivées : <code>D3PStack</code>, <code>D3PWaterfall</code> et <code>D3PHistogram</code> prennent des séries et en produisent d&#39;autres, qu&#39;ils tiennent à jour.</p><h2 id="domaines-axes-et-echelles" tabindex="-1">Domaines, axes et échelles <a class="header-anchor" href="#domaines-axes-et-echelles" aria-label="Permalink to “Domaines, axes et échelles”">​</a></h2><p>Un <strong>domaine</strong> (<code>D3PAxisDomain</code>) est la plage de valeurs qu&#39;un axe montre : deux nombres, deux dates, ou une liste de catégories. Il ne sait rien d&#39;autre, pas même ce qu&#39;est un axe. On peut l&#39;écrire, et tout ce qui en dépend suit : zoomer, c&#39;est écrire un domaine.</p><p>Un <strong>axe</strong> (<code>D3PAxis</code>) a un domaine, un nom, une position (<code>bottom</code>, <code>top</code>, <code>left</code>, <code>right</code>, ou <code>angle</code> et <code>radius</code> en polaire) et un type d&#39;échelle (<code>linear</code>, <code>time</code>, <code>log</code>, <code>band</code>...). Il construit son échelle à partir du domaine et de la taille du graphique, se dessine (graduations, étiquettes, grille), et répond à deux questions : où est cette valeur (<code>axis.projectTo</code>), et quelle valeur est ici (<code>axis.projectFrom</code>).</p><p>Un <strong>domaine automatique</strong> (<code>D3PAutoDomain</code>) règle des domaines d&#39;après les données de séries, et les tient à jour. Voir l&#39;<a href="/fr/guide/axes-and-domains">étape 2</a>.</p><p><strong>Plusieurs axes.</strong> Un graphique prend autant d&#39;axes qu&#39;on lui en donne, des deux côtés, avec des échelles de natures différentes. Un rendu nomme les axes avec lesquels il dessine par son option <code>axes</code> ; sans elle, il prend le premier axe x et le premier axe y du même système. Voir l&#39;<a href="/fr/guide/several-axes">étape 7</a>.</p><h2 id="systemes-de-coordonnees" tabindex="-1">Systèmes de coordonnées <a class="header-anchor" href="#systemes-de-coordonnees" aria-label="Permalink to “Systèmes de coordonnées”">​</a></h2><p>Un <strong>système</strong> donne un sens aux pixels du tracé. Il en existe deux : <em>cartésien</em> (x vers la droite, y vers le haut : le range est en pixels) et <em>polaire</em> (un angle et une distance au centre : le range est en radians et en pixels). Un axe appartient à un système par sa position : <code>bottom</code>, <code>top</code>, <code>left</code>, <code>right</code> sont cartésiens ; <code>angle</code> et <code>radius</code> sont polaires. Le système est créé avec le premier axe qui en a besoin ; créez-le vous-même pour régler ses options (<code>D3PPolarSystem</code> : angle de départ, sens, étendue, trou, portée).</p><p>Plusieurs systèmes peuvent partager un graphique (une rose avec un anneau en son centre, par exemple) : nommez-les, et dirigez axes et rendus vers eux avec l&#39;option <code>system</code>.</p><p>Là où un système n&#39;a pas de place pour une valeur (hors du disque, dans le trou, au-delà de la plage d&#39;angle), rien n&#39;est dessiné et le pointeur n&#39;a pas de valeur. Voir l&#39;<a href="/fr/guide/polar">étape 9</a>.</p><h2 id="rendus" tabindex="-1">Rendus <a class="header-anchor" href="#rendus" aria-label="Permalink to “Rendus”">​</a></h2><p>Un <strong>rendu</strong> (<em>renderer</em>) dessine une série : courbes, aires, barres, points, chandeliers, une carte de chaleur, un camembert... Il reçoit son apparence de ses <code>props</code> (couleur, courbe, épaisseur...), et peut dire ce qui est sous le pointeur et comment le marquer. Certains rendus n&#39;ont de sens qu&#39;en cartésien (un chandelier) et le disent quand on leur donne des axes polaires. Voir l&#39;<a href="/fr/guide/chart-kinds">étape 8</a> et les <a href="/fr/examples/gallery">types de graphiques</a>.</p><p>Un rendu donne aussi des entrées à la légende (un camembert en a une par part) et un <strong>marker</strong> : le point, le contour ou la mise en évidence qui montre le point sous le pointeur. Le marker appartient au rendu parce que lui seul sait quoi mettre en évidence ; donnez-en un autre, ou aucun.</p><h2 id="le-pointeur" tabindex="-1">Le pointeur <a class="header-anchor" href="#le-pointeur" aria-label="Permalink to “Le pointeur”">​</a></h2><p>Trois éléments interviennent pour le pointeur, et chacun s&#39;utilise seul.</p><ul><li><strong>La zone d&#39;interaction</strong> est un rectangle transparent sur le tracé : la seule source des événements souris (<code>mousemove</code>, <code>mousedown</code>, <code>wheel</code>, <code>drag</code>...). Les graphiques Vue et React la créent ; en TypeScript pur, <code>d3pAutoInteractionArea(chart)</code> le fait.</li><li><strong>Les outils</strong> agissent sur le graphique : déplacement, zoom, zoom sur sélection, réinitialisation. Un outil ne fait qu&#39;une chose : il écrit les domaines des axes qu&#39;on lui donne. Voir l&#39;<a href="/fr/guide/zoom-and-pan">étape 5</a>.</li><li><strong>Le curseur, l&#39;infobulle et les markers</strong> montrent ce qui est sous le pointeur. Ils interrogent la <em>sonde</em> (<em>probe</em>) du graphique, qui trouve pour un événement la valeur de chaque axe et le point que chaque rendu montrerait. Voir l&#39;<a href="/fr/guide/hover">étape 4</a>.</li></ul><h2 id="mise-en-page" tabindex="-1">Mise en page <a class="header-anchor" href="#mise-en-page" aria-label="Permalink to “Mise en page”">​</a></h2><p>La place autour du tracé est distribuée en <strong>bandes</strong> : des bandes le long d&#39;un côté du graphique qu&#39;un objet réserve, et que le tracé cède. Un <strong>slot</strong> est une bande et un élément HTML placé dessus. Les titres, les titres d&#39;axes et la légende standard sont faits de slots ; vos propres composants peuvent l&#39;être. Voir l&#39;<a href="/fr/guide/layout">étape 6</a>.</p><h2 id="plusieurs-graphiques" tabindex="-1">Plusieurs graphiques <a class="header-anchor" href="#plusieurs-graphiques" aria-label="Permalink to “Plusieurs graphiques”">​</a></h2><p>Deux axes construits sur le même domaine montrent la même plage, même sur deux graphiques : faites glisser sur l&#39;un et l&#39;autre suit. Les outils, le curseur et l&#39;infobulle peuvent être attachés à plusieurs graphiques à la fois ; ils trouvent les axes de chaque graphique par leur <strong>nom</strong>, donc donnez les mêmes noms aux axes qui veulent dire la même chose.</p><p>Une <strong>jointure</strong> (<em>join</em>) dit que des axes de noms différents, ou de systèmes différents, décrivent la même grandeur : un temps sur un axe x cartésien et l&#39;angle d&#39;un graphique polaire. Avec elle, le pointeur passe de l&#39;un à l&#39;autre, avec une conversion si les unités diffèrent.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// le temps (0-100) de l&#39;axe cartésien est un angle (0-360 degrés) sur le polaire</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chart.coords.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">join</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ axes: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;time&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;angle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (value </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// ou seulement pour une infobulle</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> D3PTooltip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ bus, joins: [{ axes: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;angle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;time&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (from </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;time&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (v </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.6</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (v </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }] })</span></span></code></pre></div><p>Les axes de même nom, et les axes qui partagent un domaine, sont joints sans qu&#39;on le dise. Voir les exemples <a href="/fr/examples/synced">graphiques synchronisés</a> et <a href="/fr/examples/polarsync">cartésien et polaire, synchronisés</a>.</p><h2 id="quand-les-choses-sont-dessinees" tabindex="-1">Quand les choses sont dessinées <a class="header-anchor" href="#quand-les-choses-sont-dessinees" aria-label="Permalink to “Quand les choses sont dessinées”">​</a></h2><p>Écrire est immédiat, dessiner ne l&#39;est pas. Quand vous changez un domaine, une prop ou des données, le graphique ne se redessine pas aussitôt : les changements d&#39;une image sont rassemblés et dessinés ensemble à la prochaine image d&#39;animation. Lire juste après avoir écrit est toujours juste (un axe reconstruit son échelle depuis le domaine à chaque lecture), mais le SVG est à jour un instant plus tard. En test, <code>await d3pSettle(bus)</code> attend que tout soit dessiné.</p><p>Le dessin est animé quand les données changent et pas quand l&#39;utilisateur zoome ou déplace, pour que le glissement ne traîne jamais derrière le pointeur.</p><h2 id="couches" tabindex="-1">Couches <a class="header-anchor" href="#couches" aria-label="Permalink to “Couches”">​</a></h2><p>Un graphique dessine par couches, depuis le fond : <code>background</code>, <code>axis</code>, <code>data</code>, <code>annotation</code>, <code>markers</code> (points et contours sous le pointeur), <code>overlay</code> (le curseur et l&#39;infobulle), <code>interaction</code>. <code>frame</code> est à part : il est dans les coordonnées du SVG, pas du tracé, et porte ce qui entoure le tracé.</p><h2 id="aller-plus-loin" tabindex="-1">Aller plus loin <a class="header-anchor" href="#aller-plus-loin" aria-label="Permalink to “Aller plus loin”">​</a></h2><ul><li><a href="/fr/guide/advanced">Avancé</a> : événements, bus, services, projections, écrire ses propres objets.</li><li><a href="/fr/guide/chart-types">Référence des types de graphiques</a> : comment chaque type est construit.</li><li><a href="/fr/examples/showcase">Exemples</a> : des graphiques en direct avec leur code.</li></ul>`,44)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};